contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable {
        require(amount == 0);
        uint256 balanceBefore = address(c).balance;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = address(c).balance;
        assert(balanceAfter == balanceBefore);
    }

    receive() external payable {}
}

